mapper.select:
SELECT m.*,
    CASE m.sendertype
        WHEN 1 THEN (SELECT realname FROM admin WHERE adminid = m.senderid)
        WHEN 2 THEN (SELECT teachername FROM teacher WHERE teacherid = m.senderid)
    END as sendername
FROM message m
WHERE m.receivertype = #{receivertype} AND m.receiverid = #{receiverid}

    AND m.isread = #{isread}

ORDER BY m.createtime DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM message
WHERE receivertype = #{receivertype} AND receiverid = #{receiverid}

    AND isread = #{isread}
